static String explainDriverForUrl(String url) {
  if (url.startsWith("jdbc:h2:")) return "com.h2database:h2";
  if (url.startsWith("jdbc:postgresql:")) return "org.postgresql:postgresql";
  if (url.startsWith("jdbc:mysql:")) return "com.mysql:mysql-connector-j";
  return "nieznana baza danych";
}

