class UnsupportedDatabaseException extends RuntimeException {
  UnsupportedDatabaseException(String message, Throwable cause) { super(message, cause); }
}
static Connection connectOrThrow(String url) {
  try { return DriverManager.getConnection(url); }
  catch (SQLException e) { throw new UnsupportedDatabaseException("Brak drivera dla URL: " + url, e); }
}

static void printDriverDiagnostics(String url) throws SQLException {
  try (Connection c = DriverManager.getConnection(url)) {
    DatabaseMetaData meta = c.getMetaData();
    System.out.println("URL: " + meta.getURL());
    System.out.println("Driver: " + meta.getDriverName() + " " + meta.getDriverVersion());
    System.out.println("Produkt: " + meta.getDatabaseProductName() + " " + meta.getDatabaseProductVersion());
    System.out.println("Liczba driverow: " + countDrivers());
  }
}

static Connection createConnection(String dbType, String id) throws SQLException {
  return switch (dbType) {
    case "h2" -> DriverManager.getConnection("jdbc:h2:mem:" + id + ";DB_CLOSE_DELAY=-1");
    case "postgresql", "mysql" -> throw new UnsupportedOperationException("Driver " + dbType + " nie jest na classpath tego projektu");
    default -> throw new IllegalArgumentException("Nieznany typ: " + dbType);
  };
}

